// Full refresh over a trailing window, not an incremental sync.
//
// Attendance gets corrected days after the fact by a front desk catching up,
// and a CRM whose webhooks occasionally drop leaves the billing data quietly
// wrong with no way to identify which rows. Being quietly wrong about an
// invoice is worse than being loudly late with one.

const clinic = $('Active clinics').first().json;
const body = $input.first().json;
const bookings = Array.isArray(body) ? body : (body.bookings || body.data || []);

// An empty result and a failed API call look identical until you check.
if (!Array.isArray(bookings)) {
  return [{ json: { clinic_id: clinic.clinic_id, error: 'unreadable response', rows: [] } }];
}

const STATUS = {
  accepted: 'booked',
  pending: 'booked',
  confirmed: 'confirmed',
  attended: 'attended',
  completed: 'attended',
  noshow: 'no_show',
  no_show: 'no_show',
  cancelled: 'cancelled',
  rejected: 'cancelled'
};

const rows = bookings.map(b => {
  const raw = String(b.status || b.outcome || '').toLowerCase().replace(/[^a-z_]/g, '');
  const starts = b.startTime || b.start || b.starts_at;
  const past = new Date(starts) < new Date();
  // 'unmarked' is a state, not an absence. An appointment nobody marked is
  // not a no-show -- it is missing data, and missing data is unbilled revenue.
  const outcome = STATUS[raw] || (past ? 'unmarked' : 'booked');
  return {
    appointment_id: String(b.uid || b.id),
    clinic_id: clinic.clinic_id,
    contact_id: b.attendeeId || b.contact_id || null,
    booked_at: b.createdAt || b.booked_at || starts,
    starts_at: starts,
    outcome,
    outcome_at: outcome === 'unmarked' ? null : (b.updatedAt || null),
    outcome_source: 'calendar_sync',
    is_new_patient: b.isNewPatient !== false,
    booked_by: b.bookedByAgent ? 'agent' : 'human'
  };
}).filter(r => r.appointment_id && r.starts_at);

return [{ json: { clinic_id: clinic.clinic_id, count: rows.length, rows } }];
